using SkillTreeEdit.skilltree;

namespace ProjectTower.config;

internal class GameModeMgr
{
	public const int MODE_CLASSIC = 0;

	public const int MODE_ENHANCED = 1;

	public const int MODE_GAUNTLET = 2;

	public static int currentMode = 1;

	public static ContentManager Content;

	public static GraphicsDevice GraphicsDevice;

	public static void SetGameModeFromPlayer(Player p)
	{
		Content = Game1.game.Content;
		GraphicsDevice = Game1.game.GraphicsDevice;
		if (p.isEnhanced && currentMode != 1)
		{
			SetEnhanced(p);
		}
		else if (!p.isEnhanced && currentMode != 0)
		{
			SetClassic(p);
		}
	}

	private static void SetGauntlet(Player player)
	{
		currentMode = 2;
	}

	private static void SetEnhanced(Player player)
	{
		currentMode = 1;
		MapMgr.Reset();
		MapMgr.entityScript = null;
		MonsterCatalog.catalog = MonsterCatalog.enhanced;
		DialogMgr.dialogList = DialogMgr.enhancedDialog;
		CharDefMgr.charDefList = CharDefMgr.enhancedList;
		PropCharMgr.Init();
		CharMgr.Init();
		Creeds.Init();
		ParticleManager.Init();
		SkillTree.nodes = SkillTree.enhancedNodes;
		LootCatalog.Init();
		LootCatalog.ReadLoot("/enhanced/loot");
		MapMgr.mapBack = new Texture2D[3]
		{
			Content.Load<Texture2D>("gfx/mapback0"),
			Content.Load<Texture2D>("gfx/mapback1"),
			Content.Load<Texture2D>("gfx/mapback2")
		};
		MapMgr.worldMap = Content.Load<Texture2D>("gfx/worldmap");
		CharSequenceMgr.Init(GraphicsDevice, Content);
		PropCharMgr.Init();
		MapMgr.Init(Game1.game.Content);
		MapMgr.map.Read("/enhanced/fortress");
		int num = CharMgr.AddCharacter("hero", new Vector2(700f, -700f), 1, player.ID, 0);
		Character character = CharMgr.character[num];
		character.loc.Y = CharCols.GetGround(character.loc);
		character.SetPlayerIdx(0);
		if (player != null)
		{
			player.Activate(0);
			player.respawnLoc = character.loc;
			character.equipment.boots.SetAndAddToInventory(2, "cleric_boots", character, canDupe: false);
			character.equipment.armor.SetAndAddToInventory(2, "knight_armor", character, canDupe: false);
			character.equipment.gloves.SetAndAddToInventory(2, "shroud_gloves", character, canDupe: false);
			character.equipment.loadout[0, 0].SetAndAddToInventory(0, "sword", character, canDupe: false);
			character.equipment.loadout[1, 0].SetAndAddToInventory(0, "halberd", character, canDupe: false);
			character.equipment.loadout[0, 1].SetAndAddToInventory(1, "shield_tower", character, canDupe: false);
			character.equipment.consumable[0].SetAndAddToInventory(4, "salt1", character, canDupe: false);
			character.equipment.consumable[1].SetAndAddToInventory(4, "salt2", character, canDupe: false);
			character.equipment.consumable[2].SetAndAddToInventory(4, "icon_three", character, canDupe: false);
			character.hp = player.stats.GetHP();
			character.mp = player.stats.GetMP();
			character.stamina = player.stats.GetSP();
			player.hair = 3;
			player.hairColor = 0;
			player.skinIdx = 2;
			player.skinClass = 1;
			player.eyeColor = 2;
		}
		ScrollManager.scroll = character.loc;
		MapMgr.ProcessEntities();
	}

	private static void SetClassic(Player player)
	{
		currentMode = 0;
		MapMgr.Reset();
		MapMgr.entityScript = null;
		MonsterCatalog.catalog = MonsterCatalog.classic;
		DialogMgr.dialogList = DialogMgr.classicDialog;
		CharDefMgr.charDefList = CharDefMgr.classicList;
		PropCharMgr.Init();
		CharMgr.Init();
		Creeds.Init();
		ParticleManager.Init();
		SkillTree.nodes = SkillTree.classicNodes;
		LootCatalog.Init();
		LootCatalog.ReadLoot("/classic/loot");
		MapMgr.mapBack = new Texture2D[3]
		{
			Content.Load<Texture2D>("gfx/mapback0"),
			Content.Load<Texture2D>("gfx/mapback1"),
			Content.Load<Texture2D>("gfx/mapback2")
		};
		MapMgr.worldMap = Content.Load<Texture2D>("gfx/worldmap");
		CharSequenceMgr.Init(GraphicsDevice, Content);
		PropCharMgr.Init();
		MapMgr.Init(Game1.game.Content);
		MapMgr.map.Read("/classic/fortress");
		int num = CharMgr.AddCharacter("hero", new Vector2(700f, -700f), 1, player.ID, 0);
		Character character = CharMgr.character[num];
		character.loc.Y = CharCols.GetGround(character.loc);
		character.SetPlayerIdx(0);
		if (player != null)
		{
			player.Activate(0);
			player.respawnLoc = character.loc;
			character.equipment.boots.SetAndAddToInventory(2, "cleric_boots", character, canDupe: false);
			character.equipment.armor.SetAndAddToInventory(2, "knight_armor", character, canDupe: false);
			character.equipment.gloves.SetAndAddToInventory(2, "shroud_gloves", character, canDupe: false);
			character.equipment.loadout[0, 0].SetAndAddToInventory(0, "sword", character, canDupe: false);
			character.equipment.loadout[1, 0].SetAndAddToInventory(0, "halberd", character, canDupe: false);
			character.equipment.loadout[0, 1].SetAndAddToInventory(1, "shield_tower", character, canDupe: false);
			character.equipment.consumable[0].SetAndAddToInventory(4, "salt1", character, canDupe: false);
			character.equipment.consumable[1].SetAndAddToInventory(4, "salt2", character, canDupe: false);
			character.equipment.consumable[2].SetAndAddToInventory(4, "icon_three", character, canDupe: false);
			character.hp = player.stats.GetHP();
			character.mp = player.stats.GetMP();
			character.stamina = player.stats.GetSP();
			player.hair = 3;
			player.hairColor = 0;
			player.skinIdx = 2;
			player.skinClass = 1;
			player.eyeColor = 2;
		}
		ScrollManager.scroll = character.loc;
		MapMgr.ProcessEntities();
	}

	internal static bool IsGameEnhanced()
	{
		if (PlayerMgr.GetMainPlayer() != null && PlayerMgr.GetMainPlayer().isEnhanced)
		{
			return true;
		}
		return false;
	}
}
using System.Collections.Generic;
using ProjectTower.gamestate;
using ProjectTower.player;

namespace ProjectTower.config;

public class InputMgr
{
	public static InputProfile[] inputProfile;

	public static void Init()
	{
		inputProfile = new InputProfile[2]
		{
			new InputProfile(0),
			new InputProfile(1)
		};
	}

	internal static void ReadConfigLine(string name, string value)
	{
		for (int i = 0; i < inputProfile.Length; i++)
		{
			inputProfile[i].ReadConfig(name, value);
		}
	}

	internal static void WriteConfig(List<string> config)
	{
		for (int i = 0; i < inputProfile.Length; i++)
		{
			inputProfile[i].WriteConfig(config);
		}
	}

	internal static int GetProfIdx(Player p)
	{
		int result = 0;
		if (p != null && GameStateManager.coopPlayerIdx > -1 && GameStateManager.coopPlayerIdx == p.ID)
		{
			result = 1;
		}
		return result;
	}

	internal static bool IsMouseKeyboardActive(Player p)
	{
		int profIdx = GetProfIdx(p);
		return inputProfile[profIdx].IsMouseKeyActive();
	}
}

