	internal void ReadConfig(string name, string val)
	{
		for (int i = 0; i < 24; i++)
		{
			if (!(inputMapping[i].configName == name) || !val.Contains('|'))
			{
				continue;
			}
			try
			{
				string[] array = val.Split('|');
				if (array.Length == 2)
				{
					int num = Convert.ToInt32(array[0]);
					int num2 = Convert.ToInt32(array[1]);
					inputMapping[i].SetKey(num, InputMapping.IntKeyToName(num), num2, InputMapping.IntKeyToName(num2), 0, InputMapping.IntKeyToName(0));
				}
				else if (array.Length == 3)
				{
					int num3 = Convert.ToInt32(array[0]);
					int num4 = Convert.ToInt32(array[1]);
					int num5 = Convert.ToInt32(array[2]);
					inputMapping[i].SetKey(num3, InputMapping.IntKeyToName(num3), num4, InputMapping.IntKeyToName(num4), num5, InputMapping.IntKeyToName(num5));
				}
				else
				{
					inputMapping[i].SetKey(0, InputMapping.IntKeyToName(0), 0, InputMapping.IntKeyToName(0), 0, InputMapping.IntKeyToName(0));
				}
			}
			catch (Exception)
			{
				inputMapping[i].SetKey(0, InputMapping.IntKeyToName(0), 0, InputMapping.IntKeyToName(0), 0, InputMapping.IntKeyToName(0));
			}
		}
	}

