public class WorldEvent
{
	private string name;

	public int state;

	public const int STATE_INACTIVE = 0;

	public const int STATE_AWAITING_RING = 1;

	public const int STATE_ACTIVE = 2;

	public const int STATE_AWAITING_DEACTIVATION = 3;

	public float activeWindow;

	public float activeTime;

	public WorldEvent(string name, float activeWindow)
	{
		this.name = name;
		this.activeWindow = activeWindow;
		activeTime = activeWindow;
	}

	internal void SetTime(float seconds)
	{
		if (state == 0)
		{
			if (seconds < activeWindow)
			{
				state = 1;
			}
		}
		else
		{
			if (state != 2)
			{
				return;
			}
			string text = ((int)((activeWindow - seconds) / 60f)).ToString();
			if (seconds >= activeWindow)
			{
				state = 3;
				return;
			}
			string text2 = name;
			if (!(text2 == "death_hill"))
			{
				if (text2 == "candle_tree")
				{
					WorldEventsMgr.AddMessage("The tree glows... (" + text + "m)");
				}
			}
			else
			{
				WorldEventsMgr.AddMessage("The mountain persists... (" + text + "m)");
			}
		}
	}

	internal void Update(Player p)
	{
		if (activeTime < activeWindow)
		{
			float num = activeTime;
			activeTime += Game1.realTime;
			if ((int)(num / 60f) != (int)(activeTime / 60f))
			{
				SetTime(activeTime);
			}
		}
		switch (state)
		{
		case 1:
		{
			state = 2;
			string text = name;
			if (!(text == "death_hill"))
			{
				if (text == "candle_tree")
				{
					WorldEventsMgr.AddMessage("A tree of souls glows brightly...");
					WorldEventsMgr.candleMode = true;
				}
			}
			else if (WorldEventsMgr.eventSequence[0].FarEnoughAway(p))
			{
				WorldEventsMgr.AddMessage("A mountain of the dead rises somewhere...");
				Sequence sequence3 = WorldEventsMgr.eventSequence[0].GetSequence();
				Sequence sequence4 = WorldEventsMgr.eventSequence[1].GetSequence();
				if (sequence3 != null && sequence4 != null)
				{
					sequence3.SetToOn(MapMgr.map);
					sequence4.SetToOn(MapMgr.map);
				}
			}
			else
			{
				state = 1;
			}
			break;
		}
		case 3:
		{
			state = 0;
			string text = name;
			if (!(text == "death_hill"))
			{
				if (text == "candle_tree")
				{
					WorldEventsMgr.AddMessage("The tree of souls goes dark...");
					WorldEventsMgr.candleMode = false;
				}
			}
			else if (WorldEventsMgr.eventSequence[0].FarEnoughAway(p))
			{
				WorldEventsMgr.AddMessage("The mountain of dead vanishes...");
				Sequence sequence = WorldEventsMgr.eventSequence[0].GetSequence();
				Sequence sequence2 = WorldEventsMgr.eventSequence[1].GetSequence();
				if (sequence != null && sequence2 != null)
				{
					sequence.SetToOff(MapMgr.map);
					sequence2.SetToOff(MapMgr.map);
				}
			}
			else
			{
				state = 3;
			}
