	public struct EventSequence
	{
		public Vector2 loc;

		public string[] name;

		public bool undo;

		public int sequenceIdx;

		public EventSequence(string[] name, bool undo)
		{
			this.name = name;
			loc = default;
			this.undo = undo;
			sequenceIdx = -1;
			for (int i = 0; i < MapMgr.map.sequenceMgr.sequences.Length; i++)
			{
				Sequence sequence = MapMgr.map.sequenceMgr.sequences[i];
				if (sequence != null && sequence.name == name[0])
				{
					loc = sequence.center;
					sequenceIdx = i;
				}
			}
		}

		internal Sequence GetSequence()
		{
			if (sequenceIdx > -1)
			{
				return MapMgr.map.sequenceMgr.sequences[sequenceIdx];
			}
			return null;
		}

		internal bool FarEnoughAway(Player p)
		{
			if (p.camMgr.latestArenaIdx > -1)
			{
				return false;
			}
			float num = 1600f;
			Vector2 vector = ScrollManager.scroll - loc;
			if (vector.X > 0f - num && vector.X < num && vector.Y > 0f - num && vector.Y < num)
			{
				return false;
			}
			return true;
		}
	}

	public class WorldMessage
	{
		public const float FRAME_MAX = 5f;

		public StringBuilder[] message;

		public float frame;

		public WorldMessage(string s)
		{
			message = WordWrap.Wrap(null, s, 100, 0);
			frame = 5f;
		}

		public void Update()
		{
			frame -= Game1.frameTime;
		}

		public void Draw()
		{
			float num = 1f;
			if (frame > 4f)
			{
				num = 5f - frame;
			}
			if (frame < 1f)
			{
				num = frame;
			}
			num = 1f;
			float x = 60f;
			float num2 = ScrollManager.screenSize.Y - 200f;
			for (int i = 0; i < message.Length; i++)
			{
				Text.DrawText(message[i], new Vector2(x, num2 + (float)message.Length * 32f) + new Vector2(0f, -100f + (float)i * 32f), new Color(1f, 1f, 1f, num), 0.5f, 0);
			}
		}
	}

