namespace ProjectTower.gameservices;

public class WorldValue
{
	private int pValue;

	public int value;

	public string friendlyValue;

	public int flags;

	private int threshhold;

	public bool needsUpdate;

	public const int FLAGS_WIN = 0;

	public const int FLAGS_LOSE = 1;

	public const int FLAGS_NONE = 2;

	public WorldValue(int value, string friendlyValue, int flags)
	{
		this.value = value;
		this.friendlyValue = friendlyValue;
		this.flags = flags;
	}

	public WorldValue(int value)
	{
		this.value = value;
	}

	internal void SetValue(int number)
	{
		pValue = value;
		value = number;
		needsUpdate = true;
	}

	internal void Update(Player p)
	{
		string text = friendlyValue;
		if (!(text == "candle_count"))
		{
			if (text == "hill_bodycount")
			{
				if (threshhold == 0 && WorldValuesMgr.worldValue.ContainsKey("hill_body_threshold"))
				{
					threshhold = WorldValuesMgr.worldValue["hill_body_threshold"].value;
				}
				if (threshhold > 0)
				{
					if (value > threshhold / 2 && pValue <= threshhold / 2)
					{
						Sequence sequence = WorldEventsMgr.eventSequence[0].GetSequence();
						if (WorldEventsMgr.eventSequence[1].GetSequence().playState != 1 && sequence != null)
						{
							if (WorldEventsMgr.eventSequence[0].FarEnoughAway(p))
							{
								if (sequence.playState == 0)
								{
									WorldEventsMgr.AddMessage("A pile of the dead has formed somewhere...");
									sequence.SetToOn(MapMgr.map);
								}
							}
							else
							{
								value = pValue;
							}
						}
					}
					if (value > threshhold)
					{
						value = 0;
						WorldEventsMgr.events["death_hill"].activeTime = 0f;
					}
				}
				else
				{
					value = pValue;
				}
			}
		}
		else
		{
			if (threshhold == 0 && WorldValuesMgr.worldValue.ContainsKey("candle_threshold"))
			{
				threshhold = WorldValuesMgr.worldValue["candle_threshold"].value;
			}
			if (threshhold > 0)
			{
				WorldEventsMgr.candleVal = (float)value / (float)threshhold;
				if (WorldEventsMgr.candleVal >= 1f)
				{
					value = 0;
					WorldEventsMgr.events["candle_tree"].activeTime = 0f;
				}
			}
		}
		needsUpdate = false;
	}
}
