		if (bossFromCharacter != null)
		{
			SteamServiceMgr.IncrementStat((bossFromCharacter + "_win").ToUpper(), 1);
		}
	}

	public static void BossLoss(Character c)
	{
		string bossFromCharacter = GetBossFromCharacter(c);
		if (bossFromCharacter != null)
		{
			SteamServiceMgr.IncrementStat((bossFromCharacter + "_loss").ToUpper(), 1);
		}
	}

	public static void IncrementValue(string name, int value)
	{
		if (worldValue.ContainsKey(name))
		{
			worldValue[name].SetValue(worldValue[name].value + value);
		}
	}

