	{
		worldValue.Clear();
		for (int i = 0; i < MapMgr.map.layer[19].seg.Length; i++)
		{
			Seg seg = MapMgr.map.layer[19].seg[i];
			if (seg == null)
			{
				continue;
			}
			string[] array = seg.strFlag.Split('\n');
			for (int j = 0; j < array.Length; j++)
			{
				if (array[j].EndsWith("\r"))
				{
					array[j] = array[j].Substring(0, array[j].Length - 1);
				}
			}
			for (int k = 0; k < array.Length; k++)
			{
				string[] array2 = array[k].Split(' ');
				if (array2[0] == "boss")
				{
					AddBossWorldValue(array2[1]);
				}
			}
		}
		worldValue.Add("overall_bodycount", new WorldValue(0, "overall_bodycount", 2));
		worldValue.Add("hill_bodycount", new WorldValue(0, "hill_bodycount", 2));
		worldValue.Add("hill_body_threshold", new WorldValue(10, "hill_body_threshold", 2));
		worldValue.Add("candle_count", new WorldValue(0, "candle_count", 2));
		worldValue.Add("candle_threshold", new WorldValue(10, "candle_threshold", 2));
	}

	private static void AddBossWorldValue(string p)
	{
		if (GameServicesMgr.isEnabled)
		{
			worldValue.Add(p + "_win", new WorldValue(0, "boss " + p, 0));
			worldValue.Add(p + "_loss", new WorldValue(0, "boss " + p, 1));
		}
	}

	internal static void Update(Player p)
	{
		foreach (KeyValuePair<string, WorldValue> item in worldValue)
		{
			if (item.Value.needsUpdate)
			{
				item.Value.Update(p);
			}
		}
	}
