	public const int CATEGORY_ARMOR = 2;

	public const int CATEGORY_SHIELDS = 3;

	public const int CATEGORY_HEALING = 4;

	public const int CATEGORY_ITEM_RANDOMIZER = 5;

	public const int CATEGORY_MONSTER_RANDOMIZER = 6;

	public const int TOTAL_CATEGORIES = 7;

	public const int RANDOM_NORMAL_MONSTERS = 0;

	public const int RANDOM_SCALED_MONSTERS = 1;

	public ChallengeCategory[] category;

	private Player p;

	private const string CHALLENGE_STR = "ch@n_";

	public PlayerChallenges(Player p)
	{
		this.p = p;
		category = new ChallengeCategory[7];
		category[0] = new ChallengeCatHardcoreMode(p);
		category[1] = new ChallengeCatLoadout(p);
		category[2] = new ChallengeCatArmor(p);
		category[3] = new ChallengeCatShield(p);
		category[4] = new ChallengeCatHealing(p);
		category[5] = new ChallengeCatRandomItems(p);
		category[6] = new ChallengeCatRandomMonsters(p);
	}

	public void CopyFrom(PlayerChallenges playerChallenges)
	{
		for (int i = 0; i < category.Length; i++)
		{
			category[i].activeChallenge = playerChallenges.category[i].activeChallenge;
		}
	}

	public void SetChallengeFlags()
	{
		for (int i = 0; i < category.Length; i++)
		{
			ChallengeCategory challengeCategory = category[i];
			if (i != 5 && i != 6 && challengeCategory.activeChallenge > -1)
			{
				string item = "ch@n_" + i + "_" + challengeCategory.activeChallenge;
				if (!p.flags.Contains(item))
				{
					p.flags.Add(item);
				}
			}
		}
	}

	public void ReadFlags()
	{
		ChallengeCategory[] array = category;
		for (int i = 0; i < array.Length; i++)
		{
			array[i].activeChallenge = -1;
		}
		List<string> list = new List<string>();
		for (int j = 0; j < p.flags.Count; j++)
		{
			string text = p.flags[j];
			if (!text.StartsWith("ch@n_"))
			{
				continue;
			}
			string[] array2 = text.Split('_');
			if (array2.Length <= 2)
			{
				continue;
			}
			try
			{
				int num = Convert.ToInt32(array2[1]);
				int activeChallenge = Convert.ToInt32(array2[2]);
				if (num == 5 || num == 6)
				{
					list.Add(text);
				}
				else
				{
					category[num].activeChallenge = activeChallenge;
				}
			}
			catch
			{
			}
		}
		for (int k = 0; k < list.Count; k++)
		{
			p.flags.Remove(list[k]);
		}
	}

	internal bool CanCoop()
	{
		for (int i = 0; i < category.Length - 2; i++)
		{
			if (category[i].activeChallenge > -1)
			{
				return false;
			}
		}
		return true;
	}

	internal void Reset()
	{
		ChallengeCategory[] array = category;
		for (int i = 0; i < array.Length; i++)
		{
			array[i].activeChallenge = -1;
		}
	}
}

