public class CharSequence
{
	public struct SequenceStep
	{
		public Vector2 loc;
		public int face;
		public int anim;
		public bool upsideDown;
		public int state;
		private const int TOTAL_CHARS = 9;
		public string DataToString()
		{
			return SteamDataConversion.Int24ToString((int)loc.X) + SteamDataConversion.Int24ToString((int)loc.Y) + SteamDataConversion.Int8ToString(state * 10 + face + (upsideDown ? 2 : 0)) + SteamDataConversion.Int16ToString(anim);
		}
		public void StringToData(string s, int idx)
		{
			loc = new Vector2(SteamDataConversion.StringToInt24(s, idx * 9), SteamDataConversion.StringToInt24(s, idx * 9 + 3));
			int num = SteamDataConversion.StringToInt8(s, idx * 9 + 6);
			state = num / 10;
			face = num % 10;
			upsideDown = face / 2 == 1;
			face %= 2;
			anim = SteamDataConversion.StringToInt16(s, idx * 9 + 7);
			if (anim < 0)
			{
				anim = 0;
			}
		}
		internal void Snap(Character character)
		{
			loc = character.loc;
			face = character.face;
			upsideDown = character.buffs.GetUpsideDown();
			anim = character.anim.anim;
			state = character.state;
		}
		internal void CopyFrom(SequenceStep sequenceStep)
		{
			loc = sequenceStep.loc;
			face = sequenceStep.face;
			upsideDown = sequenceStep.upsideDown;
			anim = sequenceStep.anim;
			state = sequenceStep.state;
		}
	}
	public const int MSG_AUTHOR = 0;
	public const int MSG_EQUIPMENT = 1;
	public const int MSG_SEQUENCE = 2;
	public const int MSG_X = 3;
	public const int MSG_Y = 4;
	public const int MSG_TIME = 5;
	public SequenceStep[] sequenceStep;
	public const int TOTAL_SERIALIZED_STEPS = 18;
	public const int TOTAL_STEPS = 90;
	private const float FRAME_RATE = 20f;
	private const float PLAYBACK_RATE = 4f;
	private const int STEP_PAIRS = 4;
	private readonly int[] STEP_RANGE_MIN = new int[4] { 0, 30, 70, 80 };
	private readonly int[] STEP_RANGE_MAX = new int[4] { 4, 35, 75, 84 };
	public const int PHASE_OFF = 0;
	public const int PHASE_RECORDING = 1;
	public const int PHASE_AWAITING_SEND = 2;
	public const int PHASE_PLAYING = 3;
	public const int PHASE_BACKGROUND_RECORDING = 4;
	public const int PHASE_AWAITING_PLAY = 5;
	public int phase;
	public float frame;
	public int step;
	public const int EQUIP_LEN = 8;
	public const int SEQUENCE_LEN = 41;
	private Character character;
