	public CharSequence(int ID)
	{
		this.ID = ID;
		sequenceStep = new SequenceStep[90];
		character = new Character(0);
		character.Init("hero", default, 0, -1, 0);
	}
	public void Serialize()
	{
		if (CharMgr.character[charRecordIdx].playerIdx > -1)
		{
			Player player = CharMgr.character[charRecordIdx].GetPlayer();
			if (player != null)
			{
				for (int i = 0; i < 10; i++)
				{
					if (player.creedLevel[i] > 0)
					{
						CharMgr.character[charRecordIdx].equipment.propCreed = i;
					}
				}
			}
		}
		sequenceString = "";
		int num = 0;
		for (int j = 0; j < 4; j++)
		{
			for (int k = STEP_RANGE_MIN[j]; k < STEP_RANGE_MAX[j]; k++)
			{
				sequenceString = sequenceStep[k].DataToString() + sequenceString;
				num++;
			}
		}
		equipmentString = CharMgr.character[charRecordIdx].equipment.SerializeToString();
		int requiredIntArraySize = SteamDataConversion.GetRequiredIntArraySize(equipmentString);
		int requiredIntArraySize2 = SteamDataConversion.GetRequiredIntArraySize(sequenceString);
		if (SteamServiceMgr.sequenceBuffer == null)
		{
			SteamServiceMgr.sequenceBuffer = new int[51];
		}
		SteamServiceMgr.sequenceBuffer[0] = (int)sequenceStep[89].loc.X;
		SteamServiceMgr.sequenceBuffer[1] = (int)sequenceStep[89].loc.Y;
		SteamDataConversion.StringToIntArray(equipmentString, SteamServiceMgr.sequenceBuffer, 2, 8);
		SteamDataConversion.StringToIntArray(sequenceString, SteamServiceMgr.sequenceBuffer, 10, 41);
	}
	public void Update()
	{
		switch (phase)
		{
		case 4:
			frame += Game1.frameTime;
			if (frame > 0.05f)
			{
				for (int num5 = sequenceStep.Length - 1; num5 > 0; num5--)
				{
					sequenceStep[num5].CopyFrom(sequenceStep[num5 - 1]);
				}
				sequenceStep[0].Snap(CharMgr.character[charRecordIdx]);
				frame -= 0.05f;
			}
			if (DebugMgr.jumpSeqMode && CharMgr.character[charRecordIdx].keys.keyJump)
			{
				Serialize();
				phase = 3;
				step = 0;
				Deserialize();
				frame = 0f;
				SteamServiceMgr.GetLeaderboard("SEQ_" + SteamServiceMgr.GetLeaderboardAreaName(), 1);
			}
			break;
		case 2:
			phase = 0;
			if (CharMgr.character[charRecordIdx].playerIdx > -1)
			{
				_ = PlayerMgr.player[CharMgr.character[charRecordIdx].playerIdx];
				SteamServiceMgr.GetLeaderboard("SEQ_" + SteamServiceMgr.GetLeaderboardAreaName(), 1);
			}
			frame = 0f;
			break;
		case 5:
			if (smashIdx == -1 && CharSequenceMgr.GetAvailableRenderer())
			{
				phase = 3;
				step = 0;
				frame = 0f;
			}
			break;
		case 3:
		{
			int num = step;
			float num2 = frame;
			frame += Game1.frameTime;
			if (frame > 0.25f)
			{
				step++;
				frame -= 0.25f;
			}
			for (int i = 0; i < STEP_RANGE_MAX.Length; i++)
			{
				if (STEP_RANGE_MAX[i] == step && i != STEP_RANGE_MAX.Length - 1)
				{
					step = STEP_RANGE_MIN[i + 1];
				}
			}
			if (step >= STEP_RANGE_MAX[3])
			{
				phase = 0;
				break;
			}
			if (step >= 89)
			{
				step = 88;
				phase = 0;
			}
			int num3 = step + 1;
			for (int j = 0; j < STEP_RANGE_MAX.Length; j++)
			{
				if (STEP_RANGE_MAX[j] == num3)
				{
					num3--;
				}
			}
			float num4 = frame / 0.25f;
			_ = sequenceStep[num3].state;
			_ = sequenceStep[step].state;
			character.loc = sequenceStep[step].loc + (sequenceStep[num3].loc - sequenceStep[step].loc) * num4;
			character.anim.UpdateEyesAndMouth(Game1.frameTime);
			if (character.draw.charCloth != null)
			{
				character.draw.updateCape = true;
				for (int k = 0; k < character.draw.charCloth.Length; k++)
				{
					if (sequenceStep[step].state == 0)
					{
						character.draw.charCloth[k].groundY = character.loc.Y;
					}
					else
					{
						character.draw.charCloth[k].groundY = 0f;
					}
					character.draw.charCloth[k].Update();
				}
			}
			if (step != num)
			{
				character.face = sequenceStep[step].face;
				if (sequenceStep[step].anim != character.anim.anim)
				{
					if (sequenceStep[step].anim < 0 || sequenceStep[step].anim >= CharDefMgr.charDefList[MonsterCatalog.catalog[character.monsterIdx].defIdx].animation.Length)
					{
						Console.WriteLine("Sequence animation out of range");
						phase = 0;
						break;
					}
					character.anim.anim = sequenceStep[step].anim;
					character.anim.animName = CharDefMgr.charDefList[MonsterCatalog.catalog[character.monsterIdx].defIdx].animation[character.anim.anim].name;
					character.anim.key = 0;
					character.anim.frame = 0f;
				}
			}
			if ((int)(num2 * 30f) != (int)(frame * 30f))
			{
				ParticleManager.AddSubtractiveParticle(15, character.loc + Rand.GetRandomVec2(-30f, 30f, -80f, -10f), Rand.GetRandomVec2(-50f, 50f, -200f, 0f), Rand.GetRandomFloat(0.125f, 0.25f), 0f, -1, -1);
				ParticleManager.AddAdditiveParticle(38, character.loc + Rand.GetRandomVec2(-30f, 30f, -80f, -10f), Rand.GetRandomVec2(-50f, 50f, -200f, 0f), Rand.GetRandomFloat(0.125f, 1f), 0f, -1, -1);
			}
			try
			{
				character.anim.Update(Game1.frameTime * 0.2f, sequenceChar: true);
			}
			catch
			{
			}
			if (frame >= 4.5f)
			{
				phase = 0;
			}
			break;
		}
		}
	}
	public void Deserialize()
	{
		if (SteamServiceMgr.sequenceBuffer == null)
		{
			return;
		}
		equipmentString = SteamDataConversion.IntArrayToString(SteamServiceMgr.sequenceBuffer, 2, 8);
		sequenceString = SteamDataConversion.IntArrayToString(SteamServiceMgr.sequenceBuffer, 10, 41);
		int num = 0;
		for (int i = 0; i < 4; i++)
		{
			for (int j = STEP_RANGE_MIN[i]; j < STEP_RANGE_MAX[i]; j++)
			{
				sequenceStep[j].StringToData(sequenceString, num);
				num++;
			}
		}
		character.equipment.InitFromString(equipmentString);
	}
	public void Draw(RenderTarget2D rTarg, Effect charDrawEffect)
	{
		if (DebugMgr.vidMode != 0 || rTarg == null)
		{
			return;
		}
		bool flag = false;
		if (step < sequenceStep.Length)
		{
			flag = sequenceStep[step].upsideDown;
		}
		Vector2 screenLoc = ScrollManager.GetScreenLoc(character.loc, 0);
		float scale = ScrollManager.cannedDepth[0];
		float num = 1f;
		for (int i = 0; i < STEP_RANGE_MIN.Length; i++)
		{
			if (step == STEP_RANGE_MIN[i])
			{
				num = frame / 0.25f;
			}
		}
		for (int j = 0; j < STEP_RANGE_MAX.Length; j++)
		{
			if (step == STEP_RANGE_MAX[j] - 1)
			{
				num = 1f - frame / 0.25f;
			}
		}
		ScrollManager.GetScreenLoc(character.loc + new Vector2(0f, -50f), 0);
		int num2 = step + 1;
		for (int k = 0; k < STEP_RANGE_MAX.Length; k++)
		{
			if (STEP_RANGE_MAX[k] == num2)
			{
				num2--;
			}
		}
		float num3 = (float)step / 4f;
		float num4 = (float)num2 / 4f;
		_ = (frame - num3) / (num4 - num3);
		charDrawEffect.Parameters["a"].SetValue(num);
		SpriteTools.End();
		SpriteTools.BeginAlpha(charDrawEffect);
		SpriteTools.sprite.Draw(rTarg, screenLoc, new Rectangle(0, 0, rTarg.Width, rTarg.Height), new Color(1f, 1f, 1f, num), 0f, new Vector2(128f, flag ? 64f : 192f), scale, flag ? SpriteEffects.FlipVertically : SpriteEffects.None, 1f);
		SpriteTools.End();
		SpriteTools.BeginAlpha();
	}
	public void Write()
	{
		string text = "";
		for (int i = 0; i < sequenceStep.Length; i++)
		{
			text += sequenceStep[i].DataToString();
		}
	}
	internal void Prepare(RenderTarget2D renderTarget2D, GraphicsDevice dev)
	{
		CharRobeVertexBufferDraw.SetProjection(new Vector2(renderTarget2D.Width, renderTarget2D.Height));
		CharCapeVertexBufferDraw.SetProjection(new Vector2(renderTarget2D.Width, renderTarget2D.Height));
		dev.SetRenderTarget(renderTarget2D);
		dev.Clear(new Color(0f, 0f, 0f, 0f));
		SpriteTools.BeginAlpha();
		if (frame > 0f)
		{
			CharDef charDef = CharDefMgr.charDefList[MonsterCatalog.catalog[character.monsterIdx].defIdx];
			float scale = 1f;
			Vector2 loc = new Vector2(128f, 192f);
			int num = 0;
			Animation animation = charDef.animation[character.anim.anim];
			if (animation == null)
			{
				character.anim.anim = 0;
				character.anim.key = 0;
			}
			else if (character.anim.key >= animation.keyFrame.Length)
			{
				character.anim.key = animation.keyFrame.Length - 1;
			}
			if (character.anim.key < 0 || character.anim.key >= animation.keyFrame.Length)
			{
				character.anim.key = 0;
			}
			if (animation.keyFrame[character.anim.key].lerp)
			{
				num = animation.keyFrame[character.anim.key].frameRef;
				if (num < 0)
				{
					num = 0;
				}
				int num2 = character.anim.key + 1;
				if (num2 >= animation.keyFrame.Length)
				{
					num2 = 0;
				}
				character.draw.Draw(charDef, loc, 1 - character.face, scale, num, animation.keyFrame[num2].frameRef, actorDraw: false, -1f, tint: false, saltTint: false, dyingBossMode: false);
			}
			else
			{
				num = animation.keyFrame[character.anim.key].frameRef;
				if (num < 0)
				{
