	public static void MigrateSaves()
	{
		if (Environment.OSVersion.Platform != PlatformID.Win32NT)
		{
			return;
		}
		bool flag = false;
		if (ConfigMgr.migrated == 1)
		{
			return;
		}
		if (!Directory.Exists(GetOldSaveDir()))
		{
			flag = true;
		}
		if (Directory.Exists(GetOldSaveDir()) && new DirectoryInfo(GetOldSaveDir()).GetFiles("*.slv").Length < 1)
		{
			flag = true;
		}
		if (Directory.Exists(GetNewSaveDir()) && new DirectoryInfo(GetNewSaveDir()).GetFiles("*.slv").Length != 0)
		{
			flag = true;
		}
		if (flag)
		{
			GameLog.Init("Migration skipped.");
			ConfigMgr.migrated = 1;
			ConfigMgr.Write();
			return;
		}
		GameLog.Init("Save Migration in process...");
		Directory.CreateDirectory(GetNewSaveDir());
		if (Directory.Exists(GetOldSaveDir()))
		{
			FileInfo[] files = new DirectoryInfo(GetOldSaveDir()).GetFiles("*.slv");
			FileInfo[] array = files;
			foreach (FileInfo fileInfo in array)
			{
				fileInfo.CopyTo(Path.Combine(GetNewSaveDir(), fileInfo.Name));
			}
			ConfigMgr.migrated = 1;
			ConfigMgr.Write();
			GameLog.Init("Save Migration::Complete");
			GameLog.Init("Migrated Count::" + files?.Length);
		}
	}
